import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _get_text(expense_summary: List[Dict[str, Any]], field_type: str) -> Optional[str]:
    for item in expense_summary or []:
        if item.get("Type", {}).get("Text") == field_type:
            value = item.get("ValueDetection", {}).get("Text")
            if value:
                return value
    return None


def _extract_items(expense_documents: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    for doc in expense_documents or []:
        line_items = doc.get("LineItemGroups", [])
        for group in line_items:
            for line in group.get("LineItems", []):
                item: Dict[str, Any] = {}
                for field in line.get("LineItemExpenseFields", []):
                    field_type = field.get("Type", {}).get("Text")
                    value = field.get("ValueDetection", {}).get("Text")
                    if not field_type or value is None:
                        continue

                    key = field_type.lower()
                    if key in {"item", "description", "productcode"}:
                        item["description"] = value
                    elif key in {"quantity", "qty"}:
                        item["quantity"] = value
                    elif key in {"price", "unitprice", "unit_price"}:
                        item["unit_price"] = value
                    elif key in {"amount", "lineitemamount", "total"}:
                        item["amount"] = value
                    else:
                        item[key] = value

                if item:
                    items.append(item)

    return items


def extract_receipt_data(image_bytes: bytes, mime_type: str = "image/jpeg") -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt using Amazon Textract AnalyzeExpense.
    Requires AWS credentials in the environment, e.g. AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY.
    """
    client = boto3.client("textract")

    try:
        response = client.analyze_expense(
            Document={"Bytes": image_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract AnalyzeExpense failed: {e}") from e

    expense_documents = response.get("ExpenseDocuments", [])
    summary_fields = []
    for doc in expense_documents:
        summary_fields.extend(doc.get("SummaryFields", []))

    merchant = (
        _get_text(summary_fields, "VENDOR_NAME")
        or _get_text(summary_fields, "MERCHANT_NAME")
        or _get_text(summary_fields, "RECEIVER_NAME")
    )
    tax = _get_text(summary_fields, "TAX") or _get_text(summary_fields, "TAX_TOTAL")
    total = _get_text(summary_fields, "TOTAL")

    items = _extract_items(expense_documents)

    result = {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
        "raw_response": response,
    }
    return result


def extract_receipt_data_from_file(path: str) -> Dict[str, Any]:
    with open(path, "rb") as f:
        return extract_receipt_data(f.read())


def extract_receipt_data_from_base64(data_b64: str) -> Dict[str, Any]:
    return extract_receipt_data(base64.b64decode(data_b64))
